<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Bookmark, BriefcaseBusiness, Target } from 'lucide-vue-next'
import { RouterLink } from 'vue-router'
import WorkspaceFrame from '@/components/workspace/WorkspaceFrame.vue'
import AppMessage from '@/components/ui/AppMessage.vue'
import AppEmptyState from '@/components/ui/AppEmptyState.vue'
import { workspaceApi, type CandidateDashboardData } from '@/services/workspace'
import { oobAreaStyle } from '@/utils/oobAreaStyle'
import { vacancyInitials } from '@/utils/vacancyInitials'

const data = ref<CandidateDashboardData | null>(null)
const loading = ref(true)
const error = ref('')
const statusLabels: Record<string, string> = { RECEIVED: 'Recibida', IN_REVIEW: 'En revisión', SHORTLISTED: 'En revisión', INTERVIEW: 'Entrevista', SELECTED: 'Aceptada', REJECTED: 'Rechazada' }
const modeLabels: Record<string, string> = { ONSITE: 'Presencial', HYBRID: 'Híbrido', REMOTE: 'Remoto' }
const contractLabels: Record<string, string> = { PERMANENT: 'Permanente', TEMPORARY: 'Temporal', CONTRACT: 'Por contrato', INTERNSHIP: 'Pasantía' }
onMounted(async () => {
  try { data.value = await workspaceApi.candidateDashboard() }
  catch (e) { error.value = e instanceof Error ? e.message : 'No se pudo cargar tu panel.' }
  finally { loading.value = false }
})
</script>

<template>
  <WorkspaceFrame v-if="data" eyebrow="Espacio candidato" :title="`Hola, ${data.profile.firstName}.`" :subtitle="[data.profile.professionalArea?.name, [data.profile.municipality?.name, data.profile.department?.name].filter(Boolean).join(', ')].filter(Boolean).join(' · ') || 'Encuentra oportunidades y da seguimiento a tus postulaciones.'" :initials="data.profile.firstName.slice(0, 1) + data.profile.lastName.slice(0, 1)">
    <template #heading-action><RouterLink class="workspace__cta candidate-dashboard__primary-action" to="/jobs">Explorar vacantes <span aria-hidden="true">→</span></RouterLink></template>
    <AppMessage v-if="error" variant="error" title="No se pudo cargar tu panel" :message="error" />
    <div class="candidate-dashboard__actions" aria-label="Acciones rápidas"><RouterLink to="/candidate/profile">Editar perfil y CV</RouterLink><RouterLink to="/candidate/applications">Mis postulaciones</RouterLink><RouterLink to="/candidate/saved-jobs">Vacantes guardadas</RouterLink></div>
    <section class="workspace__grid candidate-dashboard__stats" aria-label="Resumen de actividad">
      <article class="workspace__card workspace__stat candidate-stat"><span class="candidate-stat__icon" aria-hidden="true"><BriefcaseBusiness :size="18" /></span><div class="workspace__stat-label">Postulaciones enviadas</div><div class="workspace__stat-value">{{ data.stats.applications }}</div><RouterLink to="/candidate/applications">Consultar seguimiento <span aria-hidden="true">→</span></RouterLink></article>
      <article class="workspace__card workspace__stat candidate-stat"><span class="candidate-stat__icon" aria-hidden="true"><Bookmark :size="18" /></span><div class="workspace__stat-label">Vacantes guardadas</div><div class="workspace__stat-value">{{ data.stats.savedJobs }}</div><RouterLink to="/candidate/saved-jobs">Ver guardadas <span aria-hidden="true">→</span></RouterLink></article>
      <article class="workspace__card workspace__stat candidate-stat candidate-stat--area"><span class="candidate-stat__icon" aria-hidden="true"><Target :size="18" /></span><div class="workspace__stat-label">Tu área profesional</div><div class="candidate-stat-area">{{ data.profile.professionalArea?.name ?? 'Por completar' }}</div><div class="candidate-stat__meta">{{ data.profile.specialization?.name ?? 'Añade una especialidad a tu perfil' }}</div></article>
    </section>
    <AppMessage v-if="loading" class="candidate-dashboard__loading" variant="loading" message="Cargando el resto de tu panel…" />
    <div v-else class="candidate-dashboard__columns">
      <section class="workspace__card workspace__section candidate-dashboard__activity"><header class="candidate-dashboard__section-head"><div><span class="candidate-dashboard__kicker">Seguimiento</span><h2>Actividad reciente</h2></div><RouterLink to="/candidate/applications">Ver todas <span aria-hidden="true">→</span></RouterLink></header>
        <div v-if="data.recentApplications.length" class="candidate-activity-list"><article v-for="(application,index) in data.recentApplications" :key="application.id" class="candidate-activity-row"><span class="candidate-activity-row__dot" :class="{ 'candidate-activity-row__dot--current': index === 0 }" aria-hidden="true"/><div class="candidate-activity-row__copy"><strong>{{ application.job.title }}</strong><span>{{ application.job.company.name }} · {{ new Date(application.appliedAt).toLocaleDateString('es-NI') }}</span></div><span class="workspace__pill">{{ statusLabels[application.status] ?? application.status }}</span></article></div>
        <AppEmptyState v-else title="Todavía no tienes postulaciones" description="Explora las vacantes disponibles y postúlate a las que encaoen contigo."><template #actions><RouterLink to="/jobs">Buscar vacantes</RouterLink></template></AppEmptyState>
      </section>
      <section class="workspace__card workspace__section candidate-dashboard__profile"><div class="candidate-dashboard__profile-mark">{{ data.profile.firstName.slice(0,1) }}{{ data.profile.lastName.slice(0,1) }}</div><span class="candidate-dashboard__kicker">Tu perfil profesional</span><h2>Preséntate a las empresas</h2><p>Revisa tus datos profesionales, experiencia y currículum para mantener tu perfil actualizado.</p><div class="candidate-dashboard__profile-meta"><span>{{ data.profile.professionalArea?.name ?? 'Área por completar' }}</span><span>{{ data.profile.cvUrl ? 'CV cargado' : 'CV pendiente' }}</span></div><RouterLink to="/candidate/profile" class="candidate-dashboard__profile-link">Revisar mi perfil <span aria-hidden="true">→</span></RouterLink></section>
    </div>
    <section class="workspace__card workspace__section candidate-dashboard__oobs"><header class="candidate-dashboard__section-head"><div><span class="candidate-dashboard__kicker">Oportunidades</span><h2>Vacantes recientes</h2></div><RouterLink to="/jobs">Explorar todas <span aria-hidden="true">→</span></RouterLink></header>
      <div v-if="data.jobs.length" class="candidate-oob-list"><article v-for="oob in data.jobs" :key="oob.id" class="candidate-oob-row"><div class="candidate-oob-row__heading"><span class="candidate-oob-row__mark vacancy-mark" :style="oobAreaStyle(oob.professionalArea.name, oob.id)" aria-hidden="true">{{ vacancyInitials(oob.title) }}</span><div class="candidate-oob-row__main"><RouterLink class="candidate-oob__title" :to="`/jobs/${oob.id}`">{{ oob.title }}</RouterLink><span>{{ oob.company.name }} · {{ oob.professionalArea.name }}</span></div><RouterLink class="candidate-oob-row__open" :to="`/jobs/${oob.id}`">Ver oferta <span aria-hidden="true">→</span></RouterLink></div><div class="candidate-oob-row__details"><span>{{ [oob.municipality?.name, oob.department?.name].filter(Boolean).join(", ") || 'Ubicación no especificada' }}</span><span>{{ modeLabels[oob.workMode] }} · {{ contractLabels[oob.contractType] }}</span></div></article></div>
      <AppEmptyState v-else title="No hay vacantes disponibles ahora" description="Vuelve a consultar más tarde para ver nuevas oportunidades." />
    </section>
  </WorkspaceFrame>
  <main v-else class="workspace-loading"><AppMessage v-if="loading" variant="loading" message="Cargando tu panel…" /><AppMessage v-else variant="error" title="No se pudo cargar tu panel" :message="error" /></main>
</template>

